const NotClosable = () => <BottomSheet
    type="message"
    title="Let’s update your docs"
    subtitle="Your documents have expired. Update them to keep sending money"
    illustration="money"
    closable={false}
    actions={{ primary: 'Open bot', ghost: 'All clear' }}
    {...(globals.locale === 'ru' ? { closeLabel: 'Закрыть', ...parameters.ru } : {})} />;

const Matrix = (_, { globals }) => {
  const ru = globals.locale === 'ru';
  const l = ru ? ['Обычная', 'Нажата', 'Неактивна', 'Загрузка'] : ['Default', 'Pressed', 'Disabled', 'Loading'];
  return (
  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 220px)', gap: 24, alignItems: 'center' }}>
    {(['primary', 'secondary', 'ghost'] as const).map((v) => (
      <Fragment key={v}>
        <Button variant={v} fullWidth>{l[0]}</Button>
        <Button variant={v} fullWidth pressed>{l[1]}</Button>
        <Button variant={v} fullWidth disabled>{l[2]}</Button>
        <Button variant={v} fullWidth loading>{l[3]}</Button>
      </Fragment>
    ))}
  </div>
  );
};

const WithBullets = () => <FullscreenMessage
    title="Before you send"
    subtitle="Have these ready – it takes about 3 minutes"
    illustration="cat"
    header
    actions={{ primary: 'Start' }}
    bullets={['Passport or ID card', 'Proof of address', 'A good light for the photo']}
    {...(globals.locale === 'ru' ? { backLabel: 'Назад', ...parameters.ru } : {})} />;

const NoHeaderNoIllustration = () => <FullscreenMessage
    title="Something went wrong"
    subtitle="We couldn’t check your documents. Try again in a few minutes"
    illustration={null}
    header={false}
    actions={{ primary: 'Try again' }}
    {...(globals.locale === 'ru' ? { backLabel: 'Назад', ...parameters.ru } : {})} />;

